function [qe, s, wr, we] = mtq_err(q, w, q_ref, w_ref)
%MTQ_ERR  The error the magnetorquer laws share: q_e = conj(q_ref) q (no sign fix), its sign s, the
%   reference rate in body wr and the rate error we.
%   q: real[1][4] (passed a plain number)
%   w: real[1][3] (passed a plain number)
%   q_ref: real[1][4] (passed a plain number)
%   w_ref: real[1][3] (passed a plain number)
%   returns qe: real[1][4] (passed a plain number)
%   returns s: real[1] (passed a plain number)
%   returns wr: real[1][3] (passed a plain number)
%   returns we: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    qe = zeros(4, 1);
    s = 0;
    wr = zeros(3, 1);
    we = zeros(3, 1);
    qe = asils.alg.math.qmult(asils.alg.math.qconj(q_ref), q);
    s = sign(qe(4));
    if (s == 0)
        s = 1;
    end
    h__64 = asils.alg.math.dcm(qe);
    wr = [h__64(1, 1)*w_ref(1) + h__64(1, 2)*w_ref(2) + h__64(1, 3)*w_ref(3); h__64(2, 1)*w_ref(1) + h__64(2, 2)*w_ref(2) + h__64(2, 3)*w_ref(3); h__64(3, 1)*w_ref(1) + h__64(3, 2)*w_ref(2) + h__64(3, 3)*w_ref(3)];
    we = (w - wr);
end
